  "basic": "'use client';\n\nimport React from 'react';\nimport { Card, Masonry } from '@ceebee/ui/client';\nimport type { MasonryProps } from '@ceebee/ui/client';\n\ntype MasonryItemType = NonNullable<MasonryProps<number>['items']>[number];\n\nconst heights = [150, 50, 90, 70, 110, 150, 130, 80, 50, 90, 100, 150, 60, 50, 80].map(\n  (height, index) => {\n    const item: MasonryItemType = {\n      key: `item-${index}`,\n      data: height,\n    };\n\n    if (index === 4) {\n      item.children = (\n        <Card\n          size=\"small\"\n          cover={\n            <img\n              alt=\"food\"\n              src=\"https://images.unsplash.com/photo-1491961865842-98f7befd1a60?w=523&auto=format\"\n            />\n          }\n        >\n          <Card.Meta title=\"I'm Special\" description=\"Let's have a meal\" />\n        </Card>\n      );\n    }\n\n    return item;\n  },\n);\n\nconst App: React.FC = () => (\n  <Masonry\n    columns={4}\n    gutter={16}\n    items={heights}\n    itemRender={({ data, index }) => (\n      <Card size=\"small\" style={{ height: data }}>\n        {index + 1}\n      </Card>\n    )}\n  />\n);\n\nexport default App;\n\n",
  "dynamic": "'use client';\n\nimport React, { useState } from 'react';\nimport { CloseOutlined } from '@ant-design/icons';\nimport { Button, Card, Flex, Masonry, theme } from '@ceebee/ui/client';\n\nconst heights = [150, 50, 90, 70, 110, 150, 130, 80, 50, 90, 100, 150, 70, 50, 80];\n\ntype ItemType = {\n  key: number;\n  column?: number;\n  data: number;\n};\n\nconst Update: React.FC = () => {\n  const { token } = theme.useToken();\n\n  const [items, setItems] = useState<ItemType[]>(() =>\n    heights.map((height, index) => ({\n      key: index,\n      column: index % 4,\n      data: height,\n    })),\n  );\n\n  const removeItem = (removeKey: React.Key) => {\n    setItems((prevItems) => prevItems.filter(({ key }) => key !== removeKey));\n  };\n\n  const addItem = () => {\n    setItems((prevItems) => [\n      ...prevItems,\n      {\n        key: (prevItems.at(-1)?.key ?? -1) + 1,\n        data: Math.floor(Math.random() * 100) + 50,\n      },\n    ]);\n  };\n\n  return (\n    <Flex vertical gap={16}>\n      <Masonry\n        columns={4}\n        gutter={16}\n        items={items}\n        itemRender={({ data, key }) => (\n          <Card size=\"small\" style={{ height: data }}>\n            {Number(key) + 1}\n            <Button\n              style={{\n                position: 'absolute',\n                insetBlockStart: token.paddingSM,\n                insetInlineEnd: token.paddingSM,\n              }}\n              size=\"small\"\n              icon={<CloseOutlined />}\n              onClick={() => removeItem(key)}\n            />\n          </Card>\n        )}\n        onLayoutChange={(sortedItems) => {\n          setItems((prevItems) =>\n            prevItems.map((item) => {\n              const matchItem = sortedItems.find((sortedItem) => sortedItem.key === item.key);\n              return matchItem\n                ? {\n                    ...item,\n                    column: matchItem.column,\n                  }\n                : item;\n            }),\n          );\n        }}\n      />\n      <Button block onClick={addItem}>\n        Add Item\n      </Button>\n    </Flex>\n  );\n};\n\nexport default Update;\n",
